import { useMemo } from 'react';

import { useQuickFilter } from 'components/Filter/hooks/useQuickFilter';
import { filterCommercialSelectOptions } from 'components/Filter/utils/commercialSelectOptions';
import { Select } from 'components/Form';
import { FilterRegistry } from 'domain/Filter';
import { Option } from 'models/Filters';

export const ClassificationQuickFilter = ({
  fieldKey,
  pageName,
  onValueChange,
  getCurrentValue,
}) => {
  const countryValue = getCurrentValue('country');

  const valueLabel = useMemo(() => {
    if (fieldKey === 'brand_filter_groupings') {
      return 'Classification';
    }
    return (
      FilterRegistry.getInstance().get(fieldKey)?.metadata?.displayName ??
      'Classification'
    );
  }, [fieldKey]);

  const {
    options,
    currentValue,
    handleValueChange,
    handleClear,
    showClearIcon,
  } = useQuickFilter({
    fieldKey,
    pageName,
    gaCategory: 'Classification Select',
    filterContext: { country: countryValue },
    onValueChange,
    getCurrentValue,
  });

  const filteredOptions = useMemo(() => {
    const selectableOptions = filterCommercialSelectOptions(pageName, options);

    if (fieldKey === 'brand_filter_groupings') {
      return selectableOptions.filter((opt) => opt.value === currentValue);
    }
    return selectableOptions;
  }, [options, currentValue, fieldKey, pageName]);

  return (
    <Select
      id={`${fieldKey}-select-quick-filter`}
      value={currentValue}
      options={filteredOptions}
      onValueChange={(option) => {
        const opt = Array.isArray(option) ? option[0] : option;
        handleValueChange(opt as Option);
      }}
      size="medium"
      shape="pill"
      placeholder={`Select ${valueLabel}`}
      chips
      clearChips={showClearIcon}
      onClearSingle={handleClear}
      valueLabel={valueLabel}
      searchable
    />
  );
};
